<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {api,post,stamp} from '../api'
import SopPlayer from '../components/SopPlayer.vue'
const props=defineProps<{tab:string;catalog:any}>(),rows=ref<any[]>([]),dialog=ref(false),form=ref<any>({}),preview=ref<any>(),fileInput=ref<HTMLInputElement>(),selected=ref<any>(),deviceKey=ref(''),traceCode=ref(''),trace=ref<any>(),acks=ref<any[]>([])
async function load(){try{const paths:any={sop:'/api/sop/versions',devices:'/api/admin/devices',protocols:'/api/admin/protocols',receipts:'/api/admin/receipts',messages:'/api/messages'};if(paths[props.tab])rows.value=await api(paths[props.tab])}catch(e:any){ElMessage.error(e.message)}}
function create(){form.value=props.tab==='devices'?{protocol:'generic-v1',items:[{name:'Voltage',unit:'V',lower:4.8,upper:5.2}]}:{important:false};dialog.value=true}
async function save(){try{const path=props.tab==='sop'?'/api/sop/versions':props.tab==='devices'?'/api/admin/devices':'/api/messages';const r=await post(path,form.value);deviceKey.value=r?.key||'';dialog.value=false;await load()}catch(e:any){ElMessage.error(e.message)}}
async function action(v:any,a:string){try{await post(`/api/sop/versions/${v.id}/${a}`);await load()}catch(e:any){ElMessage.error(e.message)}}
function upload(v:any){selected.value=v;fileInput.value?.click()}
async function files(e:Event){const input=e.target as HTMLInputElement;if(!input.files?.length)return;try{const f=new FormData();for(const file of input.files)f.append('files',file);await api(`/api/sop/versions/${selected.value.id}/files`,{method:'POST',body:f});await load()}catch(e:any){ElMessage.error(e.message)}input.value=''}
async function saveOrder(row:any){try{await api(`/api/sop/versions/${row.version.id}/files`,{method:'PUT',body:JSON.stringify(row.files.map((f:any)=>({id:f.id,seconds:f.seconds})))});ElMessage.success('播放顺序与停留时间已保存')}catch(e:any){ElMessage.error(e.message)}}
function move(row:any,index:number,d:number){const list=row.files;if(index+d<0||index+d>=list.length)return;[list[index],list[index+d]]=[list[index+d],list[index]]}
async function search(){try{trace.value=await api('/api/trace?code='+encodeURIComponent(traceCode.value))}catch(e:any){ElMessage.error(e.message)}}
async function ack(id:string){await post('/api/messages/'+id+'/ack');await load()}
async function deviceAction(id:string,action:string){try{const r=await post(`/api/admin/devices/${id}/${action}`);deviceKey.value=r?.key||'';await load()}catch(e:any){ElMessage.error(e.message)}}
watch(()=>props.tab,()=>{rows.value=[];load()});onMounted(load)
</script>
<template><div class="actions" style="margin-bottom:20px"><el-button v-if="['sop','devices','messages'].includes(tab)" type="primary" @click="create">＋ 新建</el-button><el-button @click="load">刷新</el-button></div><el-alert v-if="deviceKey" title="设备密钥仅显示一次，请保存到设备配置" type="warning" :closable="false"><code>{{deviceKey}}</code><el-button @click="deviceKey=''">已保存，关闭</el-button></el-alert><input ref="fileInput" type="file" multiple accept="image/png,image/jpeg,application/pdf,video/mp4,video/webm" style="display:none" @change="files"/>
<template v-if="tab==='sop'"><section v-for="row in rows" :key="row.version.id" class="panel"><div class="panelhead"><h2>{{row.version.title}} · V{{row.version.version}} · {{catalog.processes.find((p:any)=>p.id===row.version.processStepId)?.name}}</h2><span class="badge">{{row.version.status}}</span></div><el-table :data="row.files"><el-table-column prop="name" label="文件"/><el-table-column label="停留秒数" width="170"><template #default="{row:f}"><el-input-number v-model="f.seconds" :min="1" :max="3600" :disabled="row.version.status!=='Draft'"/></template></el-table-column><el-table-column label="播放顺序"><template #default="{$index}"><el-button v-if="row.version.status==='Draft'" @click="move(row,$index,-1)">上移</el-button><el-button v-if="row.version.status==='Draft'" @click="move(row,$index,1)">下移</el-button></template></el-table-column></el-table><div class="actions"><el-button @click="preview=row">逐份预览</el-button><template v-if="row.version.status==='Draft'"><el-button @click="upload(row.version)">上传多份文件</el-button><el-button @click="saveOrder(row)">保存播放设置</el-button><el-button @click="action(row.version,'review')">审核通过</el-button></template><el-button v-if="row.version.status==='Reviewed'" type="primary" @click="action(row.version,'publish')">发布并归档旧版</el-button></div></section></template>
<section v-else-if="tab==='trace'" class="panel"><div class="filters"><el-input v-model="traceCode" placeholder="主码 / 电芯码 / SN / 包装码" @keyup.enter="search"/><el-button type="primary" @click="search">追溯</el-button></div><template v-if="trace"><el-descriptions title="产品绑定" :column="2" border><el-descriptions-item v-for="(v,k) in trace.unit" :key="k" :label="String(k)">{{v}}</el-descriptions-item></el-descriptions><h2>过站记录与 SOP 版本</h2><el-table :data="trace.passages"><el-table-column prop="processStepId" label="工序 ID"/><el-table-column prop="sopVersionId" label="SOP 版本 ID"/><el-table-column prop="at" label="时间"/></el-table><h2>全部测试与复测</h2><div v-for="t in trace.tests" :key="t.result.id" class="panel"><b>{{t.result.verdict}} · {{t.result.recordId}} · {{stamp(t.result.testedAt)}}</b><el-table :data="t.items"><el-table-column v-for="p in ['name','value','unit','lower','upper','verdict']" :key="p" :prop="p" :label="p"/></el-table><details><summary>原始报文</summary><pre class="code">{{t.result.raw}}</pre></details></div></template></section>
<section v-else-if="tab==='messages'" class="panel"><div v-for="row in rows" :key="row.message.id" class="lineitem"><div class="fill"><b>{{row.message.important?'【重要】':''}}{{row.message.title}}</b><p>{{row.message.body}}</p><small>{{stamp(row.message.at)}}</small></div><el-button :disabled="row.acked" @click="ack(row.message.id)">{{row.acked?'已确认':'确认收到'}}</el-button><el-button @click="api('/api/messages/'+row.message.id+'/acks').then(x=>acks=x)">查看确认人</el-button></div><el-table v-if="acks.length" :data="acks"><el-table-column prop="name" label="确认人"/><el-table-column prop="at" label="确认时间"/></el-table></section>
<section v-else class="panel"><el-table :data="rows"><el-table-column v-for="k in (tab==='protocols'?['name','enabled','status']:tab==='devices'?['code','name','stationId','protocol','programVersion','active','lastSeen']:['at','operation','recordId','status','reason'])" :key="k" :prop="k" :label="k"/><el-table-column v-if="tab==='receipts'" type="expand"><template #default="{row}"><pre class="code">{{row.raw}}</pre></template></el-table-column><el-table-column v-if="tab==='devices'" label="凭据与状态"><template #default="{row}"><el-button @click="deviceAction(row.id,'rotate')">重置密钥</el-button><el-button type="danger" @click="deviceAction(row.id,'disable')">停用</el-button></template></el-table-column></el-table></section>
<el-dialog v-model="dialog" title="新建" width="720"><el-form label-width="110"><template v-if="tab==='sop'"><el-form-item label="工序"><el-select v-model="form.processStepId"><el-option v-for="p in catalog.processes" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item label="SOP 标题"><el-input v-model="form.title"/></el-form-item><p class="sub">创建草稿后上传文件；审核须由另一名有质量权限的用户执行。</p></template><template v-if="tab==='devices'"><el-form-item v-for="p in ['code','name','programVersion']" :key="p" :label="{code:'设备编码',name:'设备名称',programVersion:'程序标准版本'}[p]"><el-input v-model="form[p]"/></el-form-item><el-form-item label="测试工位"><el-select v-model="form.stationId"><el-option v-for="s in catalog.stations.filter((s:any)=>catalog.processes.find((p:any)=>p.id===s.processStepId)?.sequence===3)" :key="s.id" :value="s.id" :label="s.code+' '+s.name"/></el-select></el-form-item><el-alert title="通用 HTTP v1；厂家协议待文档，不可启用。" :closable="false"/><el-table :data="form.items"><el-table-column v-for="p in ['name','unit','lower','upper']" :key="p" :label="p"><template #default="{row}"><el-input-number v-if="p==='lower'||p==='upper'" v-model="row[p]" :controls="false"/><el-input v-else v-model="row[p]"/></template></el-table-column></el-table><el-button @click="form.items.push({name:'',unit:'',lower:0,upper:1})">增加测试项目</el-button></template><template v-if="tab==='messages'"><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="正文"><el-input v-model="form.body" type="textarea"/></el-form-item><el-form-item label="产线"><el-select v-model="form.lineId" clearable placeholder="全部产线"><el-option v-for="l in catalog.lines" :key="l.id" :label="l.name" :value="l.id"/></el-select></el-form-item><el-form-item label="重要消息"><el-switch v-model="form.important"/></el-form-item></template></el-form><template #footer><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-dialog :model-value="!!preview" title="SOP 逐份预览" width="85%" @close="preview=undefined"><SopPlayer v-if="preview" :preview="preview"/></el-dialog></template>
